/* Force Multiplier MXMGR Task Map. Learner-facing, offline, no external dependencies.
   Task inventory = supplied task listing; instruction = working-group synthesis, not an official JQS. */
(function(){'use strict';
const DATA=window.FMTaskMapData;
if(!DATA)return;
const M=window.FMFundamentalsData||{};
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=Object.fromEntries(DATA.tasks.map(t=>[t.id,t]));
const CATS=DATA.categories;
const fId=k=>'tmap-'+k;
function moduleFor(t){return M[t.moduleArea]?.modules?.find(x=>x.id===t.moduleId)||null;}
function findAdd(id){return DATA.additions.find((a,i)=>'proposed-'+i===id);}
function counts(){return DATA.tasks.length;}
function renderTaskRow(t,f){const done=!!f.taskReviewed?.[t.id];return `<button type="button" class="tmap-task ${done?'reviewed':''}" data-task-open="${E(t.id)}" title="Explore fundamentals: ${E(t.title)}"><span>${E(t.title)}</span><span class="tmap-task-arrow" aria-hidden="true">${done?'✓':'›'}</span></button>`;}
function renderSection(id,f){const s=DATA.sections.find(s=>s.id===id);let tasks=DATA.tasks.filter(t=>t.section===id);
 return `<section class="tmap-section ${s.kind==='wing'?'wing':''}" style="--section:${s.color}"><h3>${E(s.title)}</h3><div class="tmap-links">${tasks.map(t=>renderTaskRow(t,f)).join('')}</div></section>`;}
function columns(f){return CATS.map((c,i)=>`<div class="tmap-column" data-tmap-col="${E(c.id)}"><div class="tmap-col-head"><span class="tmap-col-number">0${i+1}</span><strong>${E(c.name)}</strong><small>${DATA.tasks.filter(t=>c.sections.includes(t.section)).length} original tasks</small></div>${c.sections.map(id=>renderSection(id,f)).join('')}</div>`).join('');}
function extra(f){return `<details class="tmap-proposed" id="tmapProposed"><summary><span><b>Additional fundamentals for the working group to validate</b><small>12 candidates derived from the workshop and 100 Skills draft; not part of the photographed task inventory.</small></span><span aria-hidden="true">⌄</span></summary><div class="tmap-proposed-grid">${DATA.additions.map((a,i)=>`<button data-task-open="proposed-${i}" class="tmap-proposed-item"><strong>${E(a.title)}</strong><span>${E(a.why)}</span><small>${a.discipline==='all'?'Applies across specialties':a.discipline==='dit_dbm'?'Data Integrity / DBM':E(a.discipline.charAt(0).toUpperCase()+a.discipline.slice(1))} →</small></button>`).join('')}</div></details>`;}
function markProgress(f){return DATA.tasks.filter(t=>f.taskReviewed?.[t.id]).length;}
function render(f={},standalone=false){const reviewed=markProgress(f);return `<div class="tmap" data-tmap-screen="overview">
 <div class="tmap-heading"><div><div class="tmap-brand">FORCE MULTIPLIER <span>REVENGE OF THE NONNER</span></div><div class="tmap-eyebrow">MXMGR / 2R2X1 · LEARN THE JOB BEFORE PLAYING THE GAME</div><h1>What must a maintenance manager know?</h1><p>Select any task to understand the fundamentals, see the evidence of good performance, and connect the lesson to hands-on simulation.</p></div><div class="tmap-heading-actions"><button type="button" data-route="academy:home" class="tmap-go">▦ Block Academy</button><button type="button" data-route="flashcards:home" class="tmap-go secondary">Flashcards</button></div></div>
 <div class="tmap-tools"><label class="tmap-searchwrap"><span>Find a task</span><input id="tmapSearch" placeholder="Checkerboard, TCTO, 9302, engine, access..." autocomplete="off" aria-label="Search original MXMGR tasks"></label><div class="tmap-stats"><strong>${DATA.tasks.length}</strong> original tasks <i>·</i> <strong>${reviewed}</strong> reviewed <i>·</i> <strong>12</strong> proposals</div></div>
 <div class="tmap-mobile-tabs" role="group" aria-label="Jump to a specialty">${CATS.map(c=>`<button data-tmap-jump="${E(c.id)}">${E(c.name)}</button>`).join('')}</div>
 <section class="tmap-map" aria-label="MXMGR task listing by specialty"><div class="tmap-columns">${columns(f)}</div></section>
 <div class="tmap-empty" id="tmapEmpty" hidden>No tasks match this search. Clear the search to see all tasks.</div>
 <div class="tmap-after-map"><div class="tmap-message"><strong>A skill is more than a term.</strong><p>Every task opens a practical explanation: what it accomplishes, the fundamental decisions, an example, typical errors, and what a supervisor should be able to observe. The game supplies repetition; an instructor still verifies real-world performance.</p></div><div class="tmap-method"><span>DISCOVER</span><b>→</b><span>EVALUATE</span><b>→</b><span>DECIDE</span><b>→</b><span>ACT</span><b>→</b><span>COMMUNICATE</span><b>→</b><span>DEFEND</span></div></div>
 ${extra(f)}
 <footer class="tmap-footer"><strong>Draft training map · 18 Nov 2026.</strong> Source tasks: supplied FGS/Wing/Engine/DIT chart; 100 Skills Working Draft; FLUX 2026 workshop. Historical 21-165 and ACCI 21-118 are background, not verified current governing guidance. Exact local tasks, references and evaluation standards require SME/CFETP validation.</footer>
 ${f.taskId?detail(f,standalone):''}
 </div>`;}
function detail(f,standalone){const t=byId[f.taskId]; if(!t){const a=findAdd(f.taskId);return a?proposedDetail(f,a,standalone):'';}
 const m=moduleFor(t); const reviewed=!!f.taskReviewed?.[t.id],choice=f.taskAnswers?.[t.id],correct=m&&choice!==undefined&&Number(choice)===m.answer;
 const isEng=t.section==='engine';
 const refs=t.refNames?.map(name=>{const s=DATA.sources[name];return s?`<a href="${E(s.url)}" target="_blank" rel="noopener noreferrer"><b>${E(name)}</b><span>${E(s.note)}</span></a>`:''}).join('')||'';
 return `<div class="tmap-backdrop" data-task-backdrop="1"><div class="tmap-dialog" role="dialog" aria-modal="true" aria-label="Fundamentals: ${E(t.title)}">
 <div class="tmap-dialog-top"><span class="tmap-group-pill" style="--pill:${t.color}">${E(t.group)}</span><span class="tmap-lesson-type">${isEng?'ENGINE MANAGEMENT TASK':t.discipline==='dit_dbm'?'SYSTEM / RECORD CONTROL':'WORKING-GROUP FUNDAMENTALS'}</span><button type="button" class="tmap-close" data-task-close="1" aria-label="Close task details">×</button></div>
 <div class="tmap-dialog-grid"><div class="tmap-dialog-main"><div class="tmap-dialog-kicker">THE FUNDAMENTALS OF</div><h2>${E(t.title)}</h2><p class="tmap-purpose">${E(t.definition)}</p><h3>What a capable 2R2 understands and does</h3><ol class="tmap-steps">${t.fundamentals.map(s=>`<li>${E(s)}</li>`).join('')}</ol>
 <div class="tmap-scenario"><strong>Practice scenario</strong><p>${E(t.scenario)}</p></div>
 ${m?`<div class="tmap-knowledge"><strong>Check your judgment</strong><p>${E(m.question)}</p><div class="tmap-options">${m.answers.map((a,i)=>`<button type="button" data-task-answer="${i}" data-for-task="${E(t.id)}" class="${choice===i?(correct?'correct':'incorrect'):''}">${String.fromCharCode(65+i)}. ${E(a)}</button>`).join('')}</div>${choice!==undefined?`<p class="tmap-quiz-feedback" role="status">${correct?'✓ Good decision.':'Not yet.'} ${E(m.answerWhy)}</p>`:''}</div>`:''}
 </div><aside class="tmap-dialog-side"><div class="tmap-proof"><h3>What good performance looks like</h3><p>${E(t.proof)}</p></div><div class="tmap-trap"><h3>Common failure to avoid</h3><p>${E(t.pitfall)}</p></div><div class="tmap-reference"><h3>Reference starting points</h3><p>Verify the current applicable publication, supplement, technical data and local instructions before operational use.</p>${refs}</div><details class="tmap-skills"><summary>Related observable skills (${t.related.length})</summary>${t.related.map(s=>`<p><b>${E(s.id)} · ${E(s.name)}</b><small>${E(s.proof)}</small></p>`).join('')}</details></aside></div>
 <div class="tmap-dialog-actions"><button type="button" data-task-reviewed="${E(t.id)}" class="tmap-button light">${reviewed?'✓ Reviewed · tap to unmark':'Mark explanation reviewed'}</button>${m?`<button type="button" data-task-learn="${E(t.id)}" class="tmap-button light">${isEng?'Read related 5-part lesson →':'Read full 5-part lesson →'}</button>`:''}<button type="button" data-task-practice="${E(t.id)}" class="tmap-button primary">${isEng?'▦ Related Block Academy practice':'▦ Practice in Block Academy'}</button><button type="button" data-task-advanced="${E(t.id)}" class="tmap-button dark">${isEng?'Related advanced trainer ↗':'Advanced trainer ↗'}</button></div>
 ${standalone?`<div class="tmap-standalone-note">Practice buttons open the included Force Multiplier application when launched from the offline package. Download the complete app ZIP for an integrated iPhone/TestFlight project.</div>`:''}
 </div></div>`;
}
function proposedDetail(f,a,standalone){const [area,id]=a.module.split('.'),m=M[area]?.modules?.find(x=>x.id===id);return `<div class="tmap-backdrop"><div class="tmap-dialog tmap-proposal-dialog" role="dialog" aria-modal="true" aria-label="Candidate skill: ${E(a.title)}"><div class="tmap-dialog-top"><span class="tmap-group-pill">WORKSHOP PROPOSAL · NOT YET APPROVED</span><button class="tmap-close" data-task-close="1">×</button></div><div class="tmap-dialog-main"><h2>${E(a.title)}</h2><p class="tmap-purpose">${E(a.why)}</p><h3>What we should teach and verify</h3><ol class="tmap-steps">${(m?.steps||['Define the task and current applicable requirements.','Perform an unfamiliar example with documented evidence.','Explain limitations, risks, and needed approvals.']).map(x=>`<li>${E(x)}</li>`).join('')}</ol><div class="tmap-scenario"><strong>Training design decision</strong><p>This is a working-group candidate derived from the previous task map and workshop synthesis. It should be checked against current CFETP/STS and real supervisor expectations before it becomes a required qualification event.</p></div></div><div class="tmap-dialog-actions"><button class="tmap-button light" data-task-close="1">Return to map</button></div></div></div>`;}
function handleClick(dataset,state,ui){const f=state.fundamentals||(state.fundamentals={});
 if(dataset.taskOpen){f.taskId=dataset.taskOpen;ui.save();ui.render();return true;}
 if(dataset.taskClose!==undefined){delete f.taskId;ui.save();ui.render();return true;}
 if(dataset.taskReviewed){f.taskReviewed=f.taskReviewed||{};f.taskReviewed[dataset.taskReviewed]=!f.taskReviewed[dataset.taskReviewed];ui.save();ui.render();return true;}
 if(dataset.taskAnswer!==undefined){const task=dataset.forTask;const t=byId[task];if(!t)return true;f.taskAnswers=f.taskAnswers||{};f.taskAnswers[task]=Number(dataset.taskAnswer);ui.save();ui.render();return true;}
 if(dataset.taskLearn){const t=byId[dataset.taskLearn];if(!t)return true;if(ui.standalone){ui.openPractice('lesson',t.moduleId);return true;}f.area=t.moduleArea;f.lesson=t.moduleId;f.screen='lesson';f.step=0;delete f.taskId;ui.save();ui.setRoute('fundamentals','home');return true;}
 if(dataset.taskPractice){const t=byId[dataset.taskPractice];if(!t)return true;delete f.taskId;ui.save();if(ui.standalone){ui.openPractice('academy',t.mission||1);return true;}const academy=state.academy||(state.academy={});academy.mission=t.mission||1;academy.round=Math.min(90,(academy.progress?.[academy.mission]||0)+1);academy.stage='play';academy.variation=0;academy.placements=null;ui.setRoute('academy','play');return true;}
 if(dataset.taskAdvanced){const t=byId[dataset.taskAdvanced];if(!t)return true;delete f.taskId;ui.save();if(ui.standalone){ui.openPractice('advanced',t.advanced);return true;}let [area,screen='home']=(t.advanced||'scheduling:home').split(':');ui.setRoute(area,screen);return true;}
 if(dataset.tmapJump){const el=document.querySelector(`[data-tmap-col="${dataset.tmapJump}"]`);el?.scrollIntoView?.({behavior:'smooth',block:'nearest',inline:'start'});return true;}
 return false;
}
function attach(root){root.addEventListener('input',ev=>{if(ev.target.id!=='tmapSearch')return;const val=ev.target.value.toLowerCase().trim();let cnt=0;const columns=root.querySelectorAll('.tmap-column');columns.forEach(col=>{let n=0;col.querySelectorAll('.tmap-task').forEach(el=>{const ok=!val||el.textContent.toLowerCase().includes(val);el.hidden=!ok;if(ok)n++;});col.querySelectorAll('.tmap-section').forEach(sec=>{sec.hidden=!Array.from(sec.querySelectorAll('.tmap-task')).some(x=>!x.hidden)});col.classList.toggle('empty',n===0);cnt+=n;});const empty=root.querySelector('#tmapEmpty');if(empty)empty.hidden=cnt>0;});}
window.FMTaskMap={DATA,render,handleClick,attach,byId};
})();
